import Foundation
import SwiftData

@Model
final class JobItem {
    var title: String
    var isFinished: Bool
    init(title: String, isFinished: Bool) {
        self.title = title
        self.isFinished = isFinished
    }
}

func fetchCompletedCount(in context: ModelContext) throws -> Int {
    let predicate = #Predicate<JobItem> { $0.isFinished == true }
    let descriptor = FetchDescriptor<JobItem>(predicate: predicate)
    return try context.fetchCount(descriptor)
}

let config = ModelConfiguration(isStoredInMemoryOnly: true)
let container = try ModelContainer(for: JobItem.self, configurations: config)
let context = ModelContext(container)
context.insert(JobItem(title: "Task 1", isFinished: true))
context.insert(JobItem(title: "Task 2", isFinished: false))
let done = try fetchCompletedCount(in: context)
print("Finished: \(done)")
